import data from "./kb.public.json";
import type { KbDecision, KbProof, KbPublic, KbStory } from "./types";

// Generated by `pnpm kb:export` from the private master; edit Me/kb/kb.json, not the JSON here.
export const KB = data as KbPublic;

export const decisionsFor = (projectId: string): KbDecision[] => KB.decisions.filter((d) => d.project === projectId);
export const proofFor = (projectId: string): KbProof[] => KB.proof.filter((p) => p.project === projectId);
export const storyById = (id: string): KbStory | undefined => KB.stories.find((s) => s.id === id);
